package com.bacapeemotetimer;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BACapeEmoteTimerConfig.GROUP)
public interface BACapeEmoteTimerConfig extends Config
{
	String GROUP = "baCapeEmoteTimer";

	@ConfigItem(
		keyName = "addMovementTick",
		name = "Add movement tick",
		description = "While you are moving, add the extra tick the emote takes when clicked mid-walk. Off always assumes you click it standing still.",
		position = 0
	)
	default boolean addMovementTick()
	{
		return false;
	}

	@ConfigItem(
		keyName = "textColor",
		name = "Text color",
		description = "Color of the emote finish time.",
		position = 1
	)
	default Color textColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "font",
		name = "Font",
		description = "Font of the emote finish time.",
		position = 2
	)
	default TimerFont font()
	{
		return TimerFont.RUNESCAPE;
	}

	@ConfigItem(
		keyName = "bold",
		name = "Bold",
		description = "Draw the emote finish time in bold.",
		position = 3
	)
	default boolean bold()
	{
		return true;
	}

	@Range(min = 8, max = 64)
	@ConfigItem(
		keyName = "fontSize",
		name = "Font size",
		description = "Size of the emote finish time text. 16 is the game's normal size.",
		position = 4
	)
	default int fontSize()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "showBackground",
		name = "Background",
		description = "Draw a rectangle behind the emote finish time.",
		position = 5
	)
	default boolean showBackground()
	{
		return false;
	}

	@ConfigItem(
		keyName = "backgroundColor",
		name = "Background color",
		description = "Color of the rectangle behind the emote finish time.",
		position = 6
	)
	default Color backgroundColor()
	{
		return Color.BLACK;
	}

	@Range(max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "backgroundOpacity",
		name = "Background opacity",
		description = "Opacity of the rectangle behind the emote finish time, from 0 (invisible) to 100 (solid).",
		position = 7
	)
	default int backgroundOpacity()
	{
		return 50;
	}
}

package com.bacapeemotetimer;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.annotation.Nullable;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.ColorUtil;

class BACapeEmoteTimerOverlay extends Overlay
{
	private static final int BACKGROUND_PADDING = 2;

	private final Client client;
	private final BACapeEmoteTimerPlugin plugin;
	private final BACapeEmoteTimerConfig config;

	private Font font;
	private TimerFont fontType;
	private boolean fontBold;
	private int fontSize;

	@Inject
	private BACapeEmoteTimerOverlay(Client client, BACapeEmoteTimerPlugin plugin, BACapeEmoteTimerConfig config)
	{
		super(plugin);
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WaveClock clock = plugin.getWaveClock();
		if (!clock.isRunning())
		{
			return null;
		}

		CapeEmote emote = plugin.equippedCapeEmote();
		if (emote == null)
		{
			return null;
		}

		Widget emoteButton = skillCapeEmoteButton();
		Widget scrollable = client.getWidget(InterfaceID.Emote.SCROLLABLE);
		if (emoteButton == null || scrollable == null)
		{
			return null;
		}

		String text = WaveClock.format(emote.finishTick(clock.elapsedTicks(client.getTickCount()), config.addMovementTick() && plugin.isMoving()));

		Rectangle button = emoteButton.getBounds();
		graphics.setFont(font());
		FontMetrics metrics = graphics.getFontMetrics();
		// Centered on the emote button
		int x = button.x + (button.width - metrics.stringWidth(text)) / 2;
		int y = button.y + (button.height + metrics.getAscent() - metrics.getDescent()) / 2;

		// The emote list scrolls, so only draw within its visible part
		Shape clip = graphics.getClip();
		graphics.clip(scrollable.getBounds());

		if (config.showBackground())
		{
			int alpha = Math.round(config.backgroundOpacity() * 255 / 100f);
			graphics.setColor(ColorUtil.colorWithAlpha(config.backgroundColor(), alpha));
			graphics.fill(backgroundBounds(x, y, metrics, text));
		}

		OverlayUtil.renderTextLocation(graphics, new Point(x, y), text, config.textColor());
		graphics.setClip(clip);
		return null;
	}

	/**
	 * The Skill Cape emote's button in the emote tab, or null while the tab is closed.
	 */
	@Nullable
	private Widget skillCapeEmoteButton()
	{
		Widget contents = client.getWidget(InterfaceID.Emote.CONTENTS);
		if (contents == null || contents.isHidden())
		{
			return null;
		}

		for (Widget button : contents.getDynamicChildren())
		{
			// The locked sprite too: the button stays unlit for a cabbage cape,
			// even though the emote can be performed
			if (button.getSpriteId() == SpriteID.Emotes.SKILLCAPE || button.getSpriteId() == SpriteID.EmotesLocked.SKILLCAPE)
			{
				return button;
			}
		}
		return null;
	}

	/**
	 * The rectangle behind text drawn with its baseline at ({@code x}, {@code baseline}),
	 * covering the text and its one-pixel drop shadow plus padding on every side.
	 */
	static Rectangle backgroundBounds(int x, int baseline, FontMetrics metrics, String text)
	{
		return new Rectangle(
			x - BACKGROUND_PADDING,
			baseline - metrics.getAscent() - BACKGROUND_PADDING,
			metrics.stringWidth(text) + 1 + 2 * BACKGROUND_PADDING,
			metrics.getAscent() + metrics.getDescent() + 1 + 2 * BACKGROUND_PADDING);
	}

	private Font font()
	{
		TimerFont type = config.font();
		boolean bold = config.bold();
		int size = config.fontSize();
		if (font == null || type != fontType || bold != fontBold || size != fontSize)
		{
			font = type.font(bold, size);
			fontType = type;
			fontBold = bold;
			fontSize = size;
		}
		return font;
	}
}

package com.bacapeemotetimer;

import com.google.inject.Provides;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "BA Cape Emote Timer",
	description = "Shows on the Skill Cape emote the Barbarian Assault wave time its emote would finish at.",
	tags = {"barbarian", "assault", "minigame", "overlay", "timer", "tick", "emote", "skillcape"}
)
public class BACapeEmoteTimerPlugin extends Plugin
{
	// Same wave-start and wave-end signals as the Barbarian Assault plugin's
	// "Wave N duration" chat message, so the two agree on a wave's length.
	private static final String WAVE_START_PREFIX = "---- Wave:";

	@Getter(AccessLevel.PACKAGE)
	private final WaveClock waveClock = new WaveClock();

	private final MovementTracker movementTracker = new MovementTracker();

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BACapeEmoteTimerOverlay overlay;

	@Provides
	BACapeEmoteTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BACapeEmoteTimerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		waveClock.stop();
		movementTracker.reset();
	}

	/**
	 * Whether the player changed tile on the latest game tick.
	 */
	boolean isMoving()
	{
		return movementTracker.isMoving();
	}

	/**
	 * The Skill Cape emote of the cape the player is wearing, or null if it has none.
	 */
	@Nullable
	CapeEmote equippedCapeEmote()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return null;
		}

		Item cape = worn.getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
		return cape == null ? null : CapeEmote.forItem(cape.getId());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE && event.getMessage().startsWith(WAVE_START_PREFIX))
		{
			// Counting from the message's own tick reads one tick ahead of the wave
			// (checked in game), so the wave's first tick is the one after it.
			waveClock.start(client.getTickCount() + 1);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		movementTracker.update(player == null ? null : player.getWorldLocation());
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// Set while inside a wave, cleared on leaving it (completion, death or exiting)
		if (event.getVarbitId() == VarbitID.BARBASSAULT_AREAEXIT_PENDING && event.getValue() == 0)
		{
			waveClock.stop();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			waveClock.stop();
			movementTracker.reset();
		}
	}
}

package com.bacapeemotetimer;

import com.google.common.collect.ImmutableMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Getter;
import net.runelite.api.gameval.ItemID;

/**
 * The Skill Cape emote of each cape that has one, with the number of game ticks
 * the emote stalls the player for.
 *
 * <p>Stall lengths are transcribed whole from the "Emote durations" table of
 * https://oldschool.runescape.wiki/w/Skill_Cape_(emote). Trimmed and untrimmed capes
 * share an emote, and every max cape variant performs the max cape emote. The music
 * cape has no Skill Cape emote (it grants Air Guitar instead), so it is not listed.
 */
enum CapeEmote
{
	AGILITY(7, ItemID.SKILLCAPE_AGILITY, ItemID.SKILLCAPE_AGILITY_TRIMMED,
		ItemID.SKILLCAPE_AGILITY_WORN, ItemID.SKILLCAPE_AGILITY_TRIMMED_WORN),
	ATTACK(6, ItemID.SKILLCAPE_ATTACK, ItemID.SKILLCAPE_ATTACK_TRIMMED),
	CONSTRUCTION(12, ItemID.SKILLCAPE_CONSTRUCTION, ItemID.SKILLCAPE_CONSTRUCTION_TRIMMED),
	COOKING(25, ItemID.SKILLCAPE_COOKING, ItemID.SKILLCAPE_COOKING_TRIMMED),
	CRAFTING(13, ItemID.SKILLCAPE_CRAFTING, ItemID.SKILLCAPE_CRAFTING_TRIMMED),
	DEFENCE(8, ItemID.SKILLCAPE_DEFENCE, ItemID.SKILLCAPE_DEFENCE_TRIMMED),
	FARMING(10, ItemID.SKILLCAPE_FARMING, ItemID.SKILLCAPE_FARMING_TRIMMED),
	FIREMAKING(7, ItemID.SKILLCAPE_FIREMAKING, ItemID.SKILLCAPE_FIREMAKING_TRIMMED),
	FISHING(12, ItemID.SKILLCAPE_FISHING, ItemID.SKILLCAPE_FISHING_TRIMMED),
	FLETCHING(13, ItemID.SKILLCAPE_FLETCHING, ItemID.SKILLCAPE_FLETCHING_TRIMMED),
	HERBLORE(14, ItemID.SKILLCAPE_HERBLORE, ItemID.SKILLCAPE_HERBLORE_TRIMMED),
	HITPOINTS(6, ItemID.SKILLCAPE_HITPOINTS, ItemID.SKILLCAPE_HITPOINTS_TRIMMED),
	HUNTER(12, ItemID.SKILLCAPE_HUNTING, ItemID.SKILLCAPE_HUNTING_TRIMMED),
	MAGIC(5, ItemID.SKILLCAPE_MAGIC, ItemID.SKILLCAPE_MAGIC_TRIMMED),
	MINING(8, ItemID.SKILLCAPE_MINING, ItemID.SKILLCAPE_MINING_TRIMMED),
	PRAYER(10, ItemID.SKILLCAPE_PRAYER, ItemID.SKILLCAPE_PRAYER_TRIMMED),
	RANGED(9, ItemID.SKILLCAPE_RANGING, ItemID.SKILLCAPE_RANGING_TRIMMED),
	RUNECRAFT(10, ItemID.SKILLCAPE_RUNECRAFTING, ItemID.SKILLCAPE_RUNECRAFTING_TRIMMED),
	SAILING(15, ItemID.SKILLCAPE_SAILING, ItemID.SKILLCAPE_SAILING_TRIMMED),
	SLAYER(5, ItemID.SKILLCAPE_SLAYER, ItemID.SKILLCAPE_SLAYER_TRIMMED),
	SMITHING(20, ItemID.SKILLCAPE_SMITHING, ItemID.SKILLCAPE_SMITHING_TRIMMED),
	STRENGTH(15, ItemID.SKILLCAPE_STRENGTH, ItemID.SKILLCAPE_STRENGTH_TRIMMED),
	THIEVING(5, ItemID.SKILLCAPE_THIEVING, ItemID.SKILLCAPE_THIEVING_TRIMMED),
	WOODCUTTING(20, ItemID.SKILLCAPE_WOODCUTTING, ItemID.SKILLCAPE_WOODCUTTING_TRIMMED),
	QUEST_POINT(15, ItemID.SKILLCAPE_QP, ItemID.SKILLCAPE_QP_TRIMMED),
	ACHIEVEMENT_DIARY(32, ItemID.SKILLCAPE_AD, ItemID.SKILLCAPE_AD_TRIMMED),
	MAX(8,
		ItemID.SKILLCAPE_MAX,
		ItemID.SKILLCAPE_MAX_WORN,
		ItemID.SKILLCAPE_MAX_FIRECAPE,
		ItemID.SKILLCAPE_MAX_FIRECAPE_BROKEN,
		ItemID.SKILLCAPE_MAX_FIRECAPE_TROUVER,
		ItemID.SKILLCAPE_MAX_SARADOMIN,
		ItemID.SKILLCAPE_MAX_ZAMORAK,
		ItemID.SKILLCAPE_MAX_GUTHIX,
		ItemID.SKILLCAPE_MAX_SARADOMIN2,
		ItemID.SKILLCAPE_MAX_SARADOMIN2_BROKEN,
		ItemID.SKILLCAPE_MAX_SARADOMIN2_TROUVER,
		ItemID.SKILLCAPE_MAX_ZAMORAK2,
		ItemID.SKILLCAPE_MAX_ZAMORAK2_BROKEN,
		ItemID.SKILLCAPE_MAX_ZAMORAK2_TROUVER,
		ItemID.SKILLCAPE_MAX_GUTHIX2,
		ItemID.SKILLCAPE_MAX_GUTHIX2_BROKEN,
		ItemID.SKILLCAPE_MAX_GUTHIX2_TROUVER,
		ItemID.SKILLCAPE_MAX_ANMA,
		ItemID.SKILLCAPE_MAX_ARDY,
		ItemID.SKILLCAPE_MAX_INFERNALCAPE,
		ItemID.SKILLCAPE_MAX_INFERNALCAPE_BROKEN,
		ItemID.SKILLCAPE_MAX_INFERNALCAPE_TROUVER,
		ItemID.SKILLCAPE_MAX_INFERNALCAPE_TROUVER_BROKEN,
		ItemID.SKILLCAPE_MAX_INFERNALCAPE_TROUVER_MANGLED,
		ItemID.SKILLCAPE_MAX_ASSEMBLER,
		ItemID.SKILLCAPE_MAX_ASSEMBLER_BROKEN,
		ItemID.SKILLCAPE_MAX_ASSEMBLER_TROUVER,
		ItemID.SKILLCAPE_MAX_ASSEMBLER_MASORI,
		ItemID.SKILLCAPE_MAX_ASSEMBLER_MASORI_BROKEN,
		ItemID.SKILLCAPE_MAX_ASSEMBLER_MASORI_TROUVER,
		ItemID.SKILLCAPE_MAX_MYTHICAL,
		ItemID.SKILLCAPE_MAX_DIZANAS,
		ItemID.SKILLCAPE_MAX_DIZANAS_BROKEN,
		ItemID.SKILLCAPE_MAX_DIZANAS_TROUVER,
		ItemID.SKILLCAPE_MAX_DIZANAS_TROUVER_BROKEN,
		ItemID.SKILLCAPE_MAX_DIZANAS_TROUVER_MANGLED),
	CABBAGE(2, ItemID.SKILLCAPE_CABBAGE),
	BANANA(9, ItemID.OSB8_SKILLCAPE_BANANA);

	private static final Map<Integer, CapeEmote> BY_ITEM_ID;

	static
	{
		ImmutableMap.Builder<Integer, CapeEmote> builder = ImmutableMap.builder();
		for (CapeEmote emote : values())
		{
			for (int itemId : emote.itemIds)
			{
				builder.put(itemId, emote);
			}
		}
		BY_ITEM_ID = builder.build();
	}

	/**
	 * Game ticks the emote stalls the player for.
	 */
	@Getter
	private final int stallTicks;

	private final int[] itemIds;

	CapeEmote(int stallTicks, int... itemIds)
	{
		this.stallTicks = stallTicks;
		this.itemIds = itemIds;
	}

	/**
	 * The emote performed while wearing the cape {@code itemId}, or null if it has none.
	 */
	@Nullable
	static CapeEmote forItem(int itemId)
	{
		return BY_ITEM_ID.get(itemId);
	}

	/**
	 * The wave tick the emote finishes on if it is clicked while the wave clock reads
	 * {@code elapsedTicks}. The click is processed on the next tick, which starts the
	 * stall, and the player is free again once all of its ticks have passed. Clicking
	 * while moving takes one tick longer.
	 */
	int finishTick(int elapsedTicks, boolean moving)
	{
		return elapsedTicks + 1 + stallTicks + (moving ? 1 : 0);
	}
}

package com.bacapeemotetimer;

import java.util.Objects;
import javax.annotation.Nullable;
import net.runelite.api.coords.WorldPoint;

/**
 * Whether the player changed tile on the latest game tick, from the tile seen on each tick.
 * Movement happens at the start of a tick, before any click made during it, so an emote
 * clicked on the tick of the player's last step still counts as clicked while moving.
 */
class MovementTracker
{
	@Nullable
	private WorldPoint lastLocation;

	private boolean moving;

	void update(@Nullable WorldPoint location)
	{
		moving = lastLocation != null && location != null && !Objects.equals(lastLocation, location);
		lastLocation = location;
	}

	void reset()
	{
		lastLocation = null;
		moving = false;
	}

	boolean isMoving()
	{
		return moving;
	}
}

package com.bacapeemotetimer;

import java.awt.Font;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.FontManager;

@RequiredArgsConstructor
public enum TimerFont
{
	RUNESCAPE("RuneScape")
	{
		@Override
		Font base(boolean bold)
		{
			// The game ships a separate bold face, so use it rather than a synthetic bold
			return bold ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeFont();
		}
	},
	RUNESCAPE_SMALL("RuneScape Small")
	{
		@Override
		Font base(boolean bold)
		{
			return FontManager.getRunescapeSmallFont().deriveFont(style(bold));
		}
	},
	SANS_SERIF("Sans-serif")
	{
		@Override
		Font base(boolean bold)
		{
			return new Font(Font.SANS_SERIF, style(bold), BASE_SIZE);
		}
	},
	SERIF("Serif")
	{
		@Override
		Font base(boolean bold)
		{
			return new Font(Font.SERIF, style(bold), BASE_SIZE);
		}
	},
	MONOSPACED("Monospaced")
	{
		@Override
		Font base(boolean bold)
		{
			return new Font(Font.MONOSPACED, style(bold), BASE_SIZE);
		}
	};

	private static final int BASE_SIZE = 16;

	private final String name;

	/**
	 * The font to draw the timer in, before the configured size is applied.
	 */
	abstract Font base(boolean bold);

	Font font(boolean bold, int size)
	{
		return base(bold).deriveFont((float) size);
	}

	private static int style(boolean bold)
	{
		return bold ? Font.BOLD : Font.PLAIN;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.bacapeemotetimer;

/**
 * Wave duration measured in game ticks, so the displayed time moves in exact
 * 0.6 second steps in lockstep with the server rather than drifting with wall-clock time.
 */
class WaveClock
{
	private static final int NOT_RUNNING = -1;

	private int startTick = NOT_RUNNING;

	void start(int tick)
	{
		startTick = tick;
	}

	void stop()
	{
		startTick = NOT_RUNNING;
	}

	boolean isRunning()
	{
		return startTick != NOT_RUNNING;
	}

	int elapsedTicks(int currentTick)
	{
		return Math.max(0, currentTick - startTick);
	}

	/**
	 * Formats a tick count as whole seconds and tenths ({@code 4.2}, {@code 123.6}),
	 * never rolling over into minutes. A tick is exactly six tenths of a second, so
	 * integer arithmetic gives the exact value with no rounding.
	 */
	static String format(int ticks)
	{
		int tenths = ticks * 6;
		return (tenths / 10) + "." + (tenths % 10);
	}
}

package com.bacapeemotetimer;

import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

class BACapeEmoteTimerOverlayTest
{
	private static FontMetrics metrics()
	{
		Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		return graphics.getFontMetrics(TimerFont.RUNESCAPE.font(true, 16));
	}

	@Nested
	class TestBackgroundBounds
	{
		@Test
		void coversTheTextAndItsShadowWithPadding()
		{
			FontMetrics metrics = metrics();
			Rectangle bounds = BACapeEmoteTimerOverlay.backgroundBounds(100, 50, metrics, "12.6");

			assertEquals(98, bounds.x);
			assertEquals(50 - metrics.getAscent() - 2, bounds.y);
			assertEquals(metrics.stringWidth("12.6") + 5, bounds.width);
			assertEquals(metrics.getAscent() + metrics.getDescent() + 5, bounds.height);
		}

		@Test
		void growsWithTheText()
		{
			FontMetrics metrics = metrics();

			assertTrue(BACapeEmoteTimerOverlay.backgroundBounds(0, 0, metrics, "100.2").width
				> BACapeEmoteTimerOverlay.backgroundBounds(0, 0, metrics, "9.6").width);
		}
	}
}

