package com.bacapeemotetimer;

import net.runelite.api.gameval.ItemID;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

class CapeEmoteTest
{
	@Test
	void stallLengthsMatchTheWiki()
	{
		// Fails if a transcribed value drifts from the wiki's "Emote durations" table
		assertEquals(7, CapeEmote.AGILITY.getStallTicks());
		assertEquals(25, CapeEmote.COOKING.getStallTicks());
		assertEquals(5, CapeEmote.MAGIC.getStallTicks());
		assertEquals(15, CapeEmote.SAILING.getStallTicks());
		assertEquals(32, CapeEmote.ACHIEVEMENT_DIARY.getStallTicks());
		assertEquals(8, CapeEmote.MAX.getStallTicks());
		assertEquals(2, CapeEmote.CABBAGE.getStallTicks());
		assertEquals(9, CapeEmote.BANANA.getStallTicks());
	}

	@Test
	void coversEveryCapeInTheWikiTable()
	{
		assertEquals(29, CapeEmote.values().length);
	}

	@Nested
	class TestForItem
	{
		@Test
		void findsUntrimmedAndTrimmedCapes()
		{
			assertEquals(CapeEmote.ATTACK, CapeEmote.forItem(ItemID.SKILLCAPE_ATTACK));
			assertEquals(CapeEmote.ATTACK, CapeEmote.forItem(ItemID.SKILLCAPE_ATTACK_TRIMMED));
			assertEquals(CapeEmote.QUEST_POINT, CapeEmote.forItem(ItemID.SKILLCAPE_QP_TRIMMED));
		}

		@Test
		void findsMaxCapeVariants()
		{
			assertEquals(CapeEmote.MAX, CapeEmote.forItem(ItemID.SKILLCAPE_MAX));
			assertEquals(CapeEmote.MAX, CapeEmote.forItem(ItemID.SKILLCAPE_MAX_INFERNALCAPE));
			assertEquals(CapeEmote.MAX, CapeEmote.forItem(ItemID.SKILLCAPE_MAX_DIZANAS));
		}

		@Test
		void hasNothingForCapesWithoutTheEmote()
		{
			assertNull(CapeEmote.forItem(ItemID.MUSIC_CAPE));
			assertNull(CapeEmote.forItem(ItemID.INFERNAL_CAPE));
		}
	}

	@Nested
	class TestFinishTick
	{
		@Test
		void startsOnTheTickAfterTheClickAndLastsTheStall()
		{
			assertEquals(1 + 1 + 6, CapeEmote.ATTACK.finishTick(1, false));
			assertEquals(100 + 1 + 32, CapeEmote.ACHIEVEMENT_DIARY.finishTick(100, false));
		}

		@Test
		void takesOneTickLongerWhileMoving()
		{
			assertEquals(1 + 1 + 6 + 1, CapeEmote.ATTACK.finishTick(1, true));
		}
	}
}

package com.bacapeemotetimer;

import net.runelite.api.coords.WorldPoint;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.Test;

class MovementTrackerTest
{
	private static final WorldPoint TILE = new WorldPoint(1900, 5250, 0);

	@Test
	void isNotMovingBeforeTwoTicksAreSeen()
	{
		MovementTracker tracker = new MovementTracker();
		assertFalse(tracker.isMoving());

		tracker.update(TILE);
		assertFalse(tracker.isMoving());
	}

	@Test
	void isMovingAfterChangingTile()
	{
		MovementTracker tracker = new MovementTracker();
		tracker.update(TILE);
		tracker.update(TILE.dx(1));

		assertTrue(tracker.isMoving());
	}

	@Test
	void stopsMovingOnceTheTileStaysTheSame()
	{
		MovementTracker tracker = new MovementTracker();
		tracker.update(TILE);
		tracker.update(TILE.dx(2));
		tracker.update(TILE.dx(2));

		assertFalse(tracker.isMoving());
	}

	@Test
	void resetForgetsTheLastTile()
	{
		MovementTracker tracker = new MovementTracker();
		tracker.update(TILE);
		tracker.reset();
		tracker.update(TILE.dx(1));

		assertFalse(tracker.isMoving());
	}
}

package com.bacapeemotetimer;

import java.awt.Font;
import net.runelite.client.ui.FontManager;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

class TimerFontTest
{
	@Nested
	class TestFont
	{
		@Test
		void runescapeUsesTheGamesBoldFace()
		{
			assertEquals(FontManager.getRunescapeBoldFont().getFamily(), TimerFont.RUNESCAPE.font(true, 16).getFamily());
		}

		@Test
		void runescapeUsesTheGamesRegularFaceWhenNotBold()
		{
			assertEquals(FontManager.getRunescapeFont().getFamily(), TimerFont.RUNESCAPE.font(false, 16).getFamily());
		}

		@Test
		void runescapeSmallIsMadeBoldOnRequest()
		{
			Font font = TimerFont.RUNESCAPE_SMALL.font(true, 16);

			assertEquals(FontManager.getRunescapeSmallFont().getFamily(), font.getFamily());
			assertTrue(font.isBold());
		}

		@Test
		void logicalFontsFollowTheBoldSetting()
		{
			assertTrue(TimerFont.MONOSPACED.font(true, 16).isBold());
			assertFalse(TimerFont.MONOSPACED.font(false, 16).isBold());
			assertEquals(Font.MONOSPACED, TimerFont.MONOSPACED.font(false, 16).getName());
		}

		@Test
		void appliesTheSize()
		{
			for (TimerFont type : TimerFont.values())
			{
				assertEquals(30, type.font(true, 30).getSize(), type.name());
			}
		}
	}
}

package com.bacapeemotetimer;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

class WaveClockTest
{
	@Test
	void isNotRunningUntilStarted()
	{
		assertFalse(new WaveClock().isRunning());
	}

	@Test
	void runsFromStartUntilStop()
	{
		WaveClock clock = new WaveClock();
		clock.start(100);
		assertTrue(clock.isRunning());

		clock.stop();
		assertFalse(clock.isRunning());
	}

	@Test
	void restartingResetsTheCount()
	{
		WaveClock clock = new WaveClock();
		clock.start(100);
		clock.start(250);

		assertEquals(5, clock.elapsedTicks(255));
	}

	@Nested
	class TestElapsedTicks
	{
		@Test
		void countsTicksSinceStart()
		{
			WaveClock clock = new WaveClock();
			clock.start(1000);

			assertEquals(0, clock.elapsedTicks(1000));
			assertEquals(1, clock.elapsedTicks(1001));
			assertEquals(50, clock.elapsedTicks(1050));
		}

		@Test
		void neverGoesNegative()
		{
			WaveClock clock = new WaveClock();
			clock.start(1000);

			assertEquals(0, clock.elapsedTicks(999));
		}
	}

	@Nested
	class TestFormat
	{
		@Test
		void startsAtZero()
		{
			assertEquals("0.0", WaveClock.format(0));
		}

		@Test
		void stepsBySixTenthsPerTick()
		{
			assertEquals("0.6", WaveClock.format(1));
			assertEquals("1.2", WaveClock.format(2));
			assertEquals("1.8", WaveClock.format(3));
			assertEquals("2.4", WaveClock.format(4));
			assertEquals("3.0", WaveClock.format(5));
		}

		@Test
		void growsDigitsInsteadOfRollingOverIntoMinutes()
		{
			assertEquals("9.6", WaveClock.format(16));
			assertEquals("10.2", WaveClock.format(17));
			assertEquals("99.6", WaveClock.format(166));
			assertEquals("100.2", WaveClock.format(167));
			assertEquals("154.2", WaveClock.format(257));
		}
	}
}
